import { readFile, stat } from "fs/promises";
import { join } from "path";

/**
 * Shared dataset loader for API routes.
 *
 * Parsed datasets are cached per-process, keyed by the source file's
 * mtime/size signature: an unchanged artifact re-serves from memory, while a
 * file regenerated by the pipeline (new mtime/size) invalidates its entry and
 * reloads on the next request instead of serving stale data until restart.
 * Concurrent cold-start requests share one in-flight load; a failed load is
 * never cached — its error propagates to the caller, which answers 500,
 * and the next request retries from disk. An artifact that parses but yields
 * no usable rows (empty or non-array) counts as failed too, so a corrupt
 * snapshot can never be cached as an empty success.
 */
export type Dataset = Record<string, unknown>[];

interface CachedDataset {
  rows: Dataset;
  signature: string;
}
const datasetCache = new Map<string, CachedDataset>();
const pendingLoads = new Map<string, Promise<Dataset>>();

/** mtime/size signature of a dataset artifact under public/. */
async function sourceSignature(file: string): Promise<string> {
  const info = await stat(join(process.cwd(), "public", file));
  return `${info.mtimeMs}:${info.size}`;
}

export async function loadDataset(file: string): Promise<Dataset> {
  const signature = await sourceSignature(file);
  const cached = datasetCache.get(file);
  if (cached && cached.signature === signature) return cached.rows;
  const existing = pendingLoads.get(file);
  if (existing) return existing;
  const pending = readFile(join(process.cwd(), "public", file), "utf-8")
    .then((raw) => {
      const parsed = JSON.parse(raw) as Dataset;
      // An empty or non-array artifact is a corrupt/partial write, not an
      // empty dataset — treat it as a failed load so it is never cached.
      if (!Array.isArray(parsed) || parsed.length === 0) {
        throw new Error(`${file}: parsed dataset is empty or not an array`);
      }
      // Signature observed before the read; a dataset swapped mid-read leaves
      // a signature/content mismatch that self-corrects on the next request.
      datasetCache.set(file, { rows: parsed, signature });
      return parsed;
    })
    .catch((error: unknown) => {
      console.error(`[datasets] failed to load ${file}:`, error);
      throw error;
    })
    .finally(() => {
      // Successes now live in datasetCache; clearing the pending slot after a
      // failure frees it so the next request retries instead of replaying the
      // rejected promise forever.
      pendingLoads.delete(file);
    });
  pendingLoads.set(file, pending);
  return pending;
}
